cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #0d1117;
  --bg-elev: #111827;
  --bg-soft: #161f2d;
  --text: #e6edf3;
  --muted: #9fb0c3;
  --border: #2a3445;
  --accent: #22d3ee;
  --accent-2: #2ee59d;
  --card-glass: rgba(255, 255, 255, 0.03);
  --max-width: 1180px;
  --radius: 14px;
  --shadow: 0 10px 28px rgba(0, 0, 0, 0.32);
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background: radial-gradient(1200px 600px at 20% -10%, #1b2a44 0%, var(--bg) 45%), var(--bg);
  color: var(--text);
  line-height: 1.6;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(var(--max-width), 92vw); margin: 0 auto; }
.topnav {
  position: sticky; top: 0; z-index: 30;
  backdrop-filter: blur(8px);
  background: rgba(13, 17, 23, 0.84);
  border-bottom: 1px solid var(--border);
}
.topnav-inner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 0;
}
.brand { font-weight: 700; letter-spacing: 0.2px; color: #fff; }
.nav-links { display: flex; gap: 18px; align-items: center; }
.nav-links a { color: var(--text); opacity: 0.9; font-size: 0.95rem; }
.nav-links a.active, .nav-links a:hover { color: #fff; opacity: 1; }
.hero { padding: 64px 0 38px; }
.hero h1 { font-size: clamp(2rem, 4vw, 3rem); line-height: 1.15; margin: 0 0 14px; }
.hero p { margin: 0; color: var(--muted); max-width: 820px; }
.cta-row { margin-top: 24px; display: flex; flex-wrap: wrap; gap: 12px; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid var(--border); color: var(--text);
  padding: 10px 14px; border-radius: 12px; background: #121b29;
  transition: 0.2s ease;
}
.btn.primary {
  background: linear-gradient(120deg, var(--accent), var(--accent-2));
  color: #042021; border: none; font-weight: 700;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.section { padding: 34px 0; }
.section h2 { margin: 0 0 10px; font-size: 1.55rem; }
.section .sub { color: var(--muted); margin: 0 0 20px; }
.grid-3, .grid-4, .grid-2 {
  display: grid; gap: 16px;
}
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.card {
  background: linear-gradient(180deg, var(--card-glass), rgba(255, 255, 255, 0.01));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
}
.card h3 { margin: 0 0 8px; font-size: 1.06rem; }
.card p { margin: 0 0 12px; color: var(--muted); font-size: 0.95rem; }
.tag {
  display: inline-block; padding: 2px 8px; border-radius: 999px;
  border: 1px solid #2f4461; color: #9ed9ff; font-size: .78rem;
}
.cli-wrap { display: grid; grid-template-columns: 280px 1fr; gap: 16px; }
.accordion-btn {
  width: 100%; text-align: left; background: #101927; color: #eaf2fa;
  border: 1px solid var(--border); border-radius: 10px; padding: 12px 14px;
  margin-bottom: 10px; font-weight: 600; cursor: pointer;
}
.accordion-btn[aria-expanded="true"] { border-color: var(--accent); }
.tabs { display: flex; gap: 8px; margin-bottom: 12px; }
.tab-btn {
  border: 1px solid var(--border); color: var(--text); background: #111a28;
  border-radius: 10px; padding: 8px 12px; cursor: pointer;
}
.tab-btn.active { border-color: var(--accent); color: #c6f8ff; }
.code {
  background: #0b1220; border: 1px solid #1f2c3f; border-radius: 10px;
  padding: 12px; overflow-x: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: .9rem;
}
.steps { margin: 12px 0 0; padding-left: 20px; color: var(--muted); }
.docs-layout {
  display: grid; grid-template-columns: 260px 1fr; gap: 18px;
  padding: 28px 0 48px;
}
.sidebar {
  border: 1px solid var(--border); background: #0f1826; border-radius: 12px; padding: 12px;
  position: sticky; top: 76px; height: fit-content;
}
.sidebar h4 { margin: 4px 0 10px; font-size: .95rem; }
.sidebar a { display: block; padding: 8px 10px; border-radius: 8px; color: #d9e3ee; font-size: .92rem; }
.sidebar a:hover { background: #162236; text-decoration: none; }
.sidebar-toggle {
  width: 100%; margin-top: 8px; border: 1px solid var(--border); background: #132034;
  color: var(--text); border-radius: 10px; padding: 8px 10px; cursor: pointer;
}
.docs-layout.collapsed { grid-template-columns: 56px 1fr; }
.docs-layout.collapsed .sidebar { padding: 8px; }
.docs-layout.collapsed .sidebar a span,
.docs-layout.collapsed .sidebar h4 { display: none; }
.docs-layout.collapsed .sidebar a { text-align: center; }
.docs-layout.collapsed .sidebar-toggle { font-size: 0; }
.docs-layout.collapsed .sidebar-toggle::after { content: "☰"; font-size: 14px; }
.content-section { margin-bottom: 24px; }
.content-section h2 { margin-bottom: 10px; }
.footer { border-top: 1px solid var(--border); padding: 24px 0 34px; color: var(--muted); font-size: .92rem; }
@media (max-width: 980px) {
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .grid-4 { grid-template-columns: 1fr 1fr; }
  .cli-wrap { grid-template-columns: 1fr; }
  .docs-layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; top: 0; }
}
@media (max-width: 640px) {
  .nav-links { gap: 12px; }
  .nav-links a { font-size: .88rem; }
  .grid-3, .grid-4, .grid-2 { grid-template-columns: 1fr; }
  .hero { padding-top: 44px; }
}
EOF

cat > /app/output/script.js <<'EOF'
(function () {
  const cliState = {
    selectedAccordion: 'apps',
    selectedTab: 'npm',
    install: {
      npm: 'npm i -g @commerceforge/cli@latest',
      yarn: 'yarn global add @commerceforge/cli@latest',
      pnpm: 'pnpm add -g @commerceforge/cli@latest'
    },
    init: {
      apps: 'commerceforge app init',
      themes: 'commerceforge theme init',
      headless: 'commerceforge hydrogen init'
    }
  };

  const stepsByAccordion = {
    apps: [
      'Install CommerceForge CLI globally.',
      'Navigate to the directory where you want to create your app.',
      'Run the second command to create a new app. Your app will be added as a new subdirectory.'
    ],
    themes: [
      'Install CommerceForge CLI globally.',
      'Navigate to the directory where you want to create your theme.',
      'Run the second command to clone a starter theme. Your theme will be created in a new subdirectory.'
    ],
    headless: [
      'Install CommerceForge CLI globally.',
      'Navigate to the directory where you want to create your Hydrogen storefront.',
      'Run the second command to initialize a Hydrogen storefront in a new subdirectory.'
    ]
  };

  function renderCli() {
    const installEl = document.getElementById('install-command');
    const initEl = document.getElementById('init-command');
    const stepsEl = document.getElementById('cli-steps');
    if (!installEl || !initEl || !stepsEl) return;

    installEl.textContent = cliState.install[cliState.selectedTab];
    initEl.textContent = cliState.init[cliState.selectedAccordion];
    stepsEl.innerHTML = stepsByAccordion[cliState.selectedAccordion]
      .map(step => `<li>${step}</li>`)
      .join('');

    document.querySelectorAll('[data-tab]').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.tab === cliState.selectedTab);
      btn.setAttribute('aria-selected', btn.dataset.tab === cliState.selectedTab ? 'true' : 'false');
    });

    document.querySelectorAll('[data-accordion]').forEach(btn => {
      const expanded = btn.dataset.accordion === cliState.selectedAccordion;
      btn.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    });
  }

  document.querySelectorAll('[data-tab]').forEach(btn => {
    btn.addEventListener('click', function () {
      cliState.selectedTab = this.dataset.tab;
      renderCli();
    });
  });

  document.querySelectorAll('[data-accordion]').forEach(btn => {
    btn.addEventListener('click', function () {
      cliState.selectedAccordion = this.dataset.accordion;
      renderCli();
    });
  });

  renderCli();

  function setupSidebar(layoutId, btnId, storageKey) {
    const layout = document.getElementById(layoutId);
    const btn = document.getElementById(btnId);
    if (!layout || !btn) return;

    const shouldAutoCollapse = window.matchMedia('(max-width: 980px)').matches;
    const saved = localStorage.getItem(storageKey);
    const collapsed = saved ? saved === '1' : shouldAutoCollapse;
    if (collapsed) layout.classList.add('collapsed');

    btn.addEventListener('click', function () {
      layout.classList.toggle('collapsed');
      const isCollapsed = layout.classList.contains('collapsed');
      localStorage.setItem(storageKey, isCollapsed ? '1' : '0');
      btn.textContent = isCollapsed ? 'Expand sidebar' : 'Collapse sidebar';
    });

    btn.textContent = layout.classList.contains('collapsed') ? 'Expand sidebar' : 'Collapse sidebar';
  }

  setupSidebar('apps-layout', 'apps-sidebar-toggle', 'cf_apps_sidebar_collapsed');
  setupSidebar('agents-layout', 'agents-sidebar-toggle', 'cf_agents_sidebar_collapsed');
})();
EOF

